import{_ as r,C as o,o as d,c as i,a5 as e,E as n}from"./chunks/framework.B5tqjWbr.js";const E=JSON.parse('{"title":"PP-10 维也纳整流器","description":"","frontmatter":{"date":"2026-06-11T00:00:00.000Z","section":"电机控制","chapter":"power-path","chapterTitle":"功率链路","chapterOrder":40,"category":"功率链路","source":"motor","visibility":"public","title":"PP-10 维也纳整流器","tags":["motor-control"],"status":"learning","summary":"> **状态**: reviewed > **定位**: 维也纳整流器是三相三电平 PFC 前端，本模块服务于“电源前级如何影响电机控制母线”的系统理解。","navGroup":"基础与硬件","navGroupOrder":20},"headers":[],"relativePath":"content/motor/power-path/PP-10-Vienna-Rectifier.md","filePath":"content/motor/power-path/PP-10-Vienna-Rectifier.md","lastUpdated":null}'),l={name:"content/motor/power-path/PP-10-Vienna-Rectifier.md"};function c(h,t,s,p,u,b){const a=o("MermaidDiagram");return d(),i("div",null,[t[0]||(t[0]=e('<h1 id="pp-10-维也纳整流器" tabindex="-1">PP-10 维也纳整流器 <a class="header-anchor" href="#pp-10-维也纳整流器" aria-label="Permalink to &quot;PP-10 维也纳整流器&quot;">​</a></h1><blockquote><p><strong>状态</strong>: reviewed<br><strong>定位</strong>: 维也纳整流器是三相三电平 PFC 前端，本模块服务于“电源前级如何影响电机控制母线”的系统理解。</p></blockquote><p><strong>模块编号：</strong> PP-10<br><strong>模块名称：</strong> 维也纳整流器<br><strong>文档版本：</strong> v1.1<br><strong>前置知识：</strong> PP-04 PFC 功率因数校正、PP-08 三电平拓扑基础、CT-04 PID 控制原理<br><strong>难度等级：</strong> ★★★★★</p><hr><h2 id="_1-📌-核心摘要-★★★★★-🔰📚" tabindex="-1">1. 📌 核心摘要 ★★★★★ 🔰📚 <a class="header-anchor" href="#_1-📌-核心摘要-★★★★★-🔰📚" aria-label="Permalink to &quot;1. 📌 核心摘要 ★★★★★ 🔰📚&quot;">​</a></h2><p><strong>一句话：</strong> 维也纳整流器是一种三相三电平单向 PFC 前端，用较少有源开关实现高功率因数、低输入电流 THD 和稳定高压直流母线；它不直接驱动电机，却决定逆变器和 FOC 能拿到怎样的母线电压。</p><p><strong>认知挂钩：</strong> 如果逆变器是电机的“功率手臂”，维也纳整流器就是前端的“呼吸系统”。它从三相电网吸取尽量正弦、同相的电流，把能量送到直流母线。呼吸不稳，后面的 FOC 再精细也会遇到母线跌落、弱磁提前、过调制和保护误触发。</p><p><strong>核心问题链：</strong></p>',8)),n(a,{code:"flowchart%20TD%0A%20%20A%5B%22%E4%B8%89%E7%9B%B8%20AC%20%E8%BE%93%E5%85%A5%22%5D%20--%3E%20B%5B%22%E7%94%B5%E6%84%9F%E9%99%90%E5%88%B6%E7%94%B5%E6%B5%81%E5%8F%98%E5%8C%96%22%5D%0A%20%20B%20--%3E%20C%5B%22%E6%9C%89%E6%BA%90%E5%BC%80%E5%85%B3%E8%B0%83%E5%88%B6%E8%BE%93%E5%85%A5%E7%94%B5%E6%B5%81%22%5D%0A%20%20C%20--%3E%20D%5B%22%E4%BA%8C%E6%9E%81%E7%AE%A1%E7%BD%91%E7%BB%9C%E6%95%B4%E6%B5%81%E8%83%BD%E9%87%8F%22%5D%0A%20%20D%20--%3E%20E%5B%22%E5%88%86%E8%A3%82%E7%9B%B4%E6%B5%81%E6%AF%8D%E7%BA%BF%E5%BB%BA%E7%AB%8B%20Vdc%22%5D%0A%20%20E%20--%3E%20F%5B%22%E9%80%86%E5%8F%98%E5%99%A8%E8%8E%B7%E5%BE%97%E7%94%B5%E5%8E%8B%E8%A3%95%E9%87%8F%22%5D%0A%20%20F%20--%3E%20G%5B%22FOC%20%E7%94%B5%E6%B5%81%E7%8E%AF%E5%92%8C%E5%BC%B1%E7%A3%81%E8%BE%B9%E7%95%8C%E5%8F%97%E7%BA%A6%E6%9D%9F%22%5D%0A"}),t[1]||(t[1]=e('<hr><h2 id="_2-🤔-问题引入-★★★★★-🔰" tabindex="-1">2. 🤔 问题引入 ★★★★★ 🔰 <a class="header-anchor" href="#_2-🤔-问题引入-★★★★★-🔰" aria-label="Permalink to &quot;2. 🤔 问题引入 ★★★★★ 🔰&quot;">​</a></h2><h3 id="工程师的真实困惑" tabindex="-1">工程师的真实困惑 <a class="header-anchor" href="#工程师的真实困惑" aria-label="Permalink to &quot;工程师的真实困惑&quot;">​</a></h3><blockquote><p><strong>场景 1：电机控制正常，但输入电流 THD 超标</strong><br> 逆变器侧 FOC 波形很好，电机运行平稳，但整机接入三相电网后输入电流畸变严重，功率因数低，无法通过电源质量测试。问题不在电机控制，而在前端整流/PFC。</p></blockquote><blockquote><p><strong>场景 2：母线电压稳定值够高，负载阶跃时却掉得很深</strong><br> 空载时 <code>Vdc = 700 V</code>，电机加速时母线瞬间跌落，FOC 电压限幅触发，电流跟踪误差增大。工程师只看稳态母线值，没有评估前端电压外环带宽和母线电容能量。</p></blockquote><blockquote><p><strong>场景 3：上下母线电容不平衡</strong><br> Vienna 输出是分裂直流母线。如果中点平衡策略不足，上下电容电压偏差会扩大，导致器件电压应力不均、输入电流畸变和后级逆变器电压参考偏移。</p></blockquote><h3 id="核心问题" tabindex="-1">核心问题 <a class="header-anchor" href="#核心问题" aria-label="Permalink to &quot;核心问题&quot;">​</a></h3><p>维也纳整流器和电机控制有什么关系？</p><p><strong>答案：</strong> 维也纳整流器不参与 dq 电流闭环，但它决定 <code>vbus</code> 的大小、纹波、跌落速度和保护边界。FOC 的电压限幅、弱磁启动点、过调制判断和故障策略都依赖母线质量。</p><h3 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h3><p>读完本模块，你将能够：</p><p>✅ 说明维也纳整流器的基本功率路径<br> ✅ 区分输入电流内环、电压外环和中点平衡环<br> ✅ 解释三相 PFC 如何获得高功率因数<br> ✅ 分析 Vienna 输出母线对 FOC 电压裕量的影响<br> ✅ 给出 Vienna 前端仿真和整机联调的关键指标</p><hr><h2 id="_3-💡-直观理解-★★★★★-🔰💡" tabindex="-1">3. 💡 直观理解 ★★★★★ 🔰💡 <a class="header-anchor" href="#_3-💡-直观理解-★★★★★-🔰💡" aria-label="Permalink to &quot;3. 💡 直观理解 ★★★★★ 🔰💡&quot;">​</a></h2><h3 id="_3-1-vienna-的定位" tabindex="-1">3.1 Vienna 的定位 <a class="header-anchor" href="#_3-1-vienna-的定位" aria-label="Permalink to &quot;3.1 Vienna 的定位&quot;">​</a></h3><p>维也纳整流器由三相电感、三相有源开关、二极管网络和分裂直流母线组成。其目标不是驱动电机，而是在三相输入侧获得接近正弦且同相的电流，同时在输出侧建立稳定直流母线。</p><p>与普通二极管整流桥相比：</p><table tabindex="0"><thead><tr><th>项目</th><th>二极管整流桥</th><th>维也纳整流器</th></tr></thead><tbody><tr><td>输入电流</td><td>脉冲形，THD 高</td><td>可控近似正弦</td></tr><tr><td>功率因数</td><td>受电容充电影响</td><td>可接近 1</td></tr><tr><td>输出母线</td><td>由电网峰值和负载决定</td><td>闭环调节</td></tr><tr><td>控制复杂度</td><td>低</td><td>高</td></tr><tr><td>能量方向</td><td>通常单向</td><td>单向</td></tr></tbody></table><h3 id="_3-2-三个控制目标" tabindex="-1">3.2 三个控制目标 <a class="header-anchor" href="#_3-2-三个控制目标" aria-label="Permalink to &quot;3.2 三个控制目标&quot;">​</a></h3><p>维也纳整流器同时追求：</p><ul><li>输入电流跟踪三相电网电压相位，实现高功率因数。</li><li>输出母线电压稳定。</li><li>上下母线电容电压平衡。</li></ul><p>这三个目标相互耦合。电压外环想提高输出功率时，会增大输入电流幅值；电流内环要把该幅值投影到三相正弦参考；中点平衡又会改变某些开关状态的选择。</p><hr><h2 id="_4-🔬-技术原理-★★★★★-📚🔧" tabindex="-1">4. 🔬 技术原理 ★★★★★ 📚🔧 <a class="header-anchor" href="#_4-🔬-技术原理-★★★★★-📚🔧" aria-label="Permalink to &quot;4. 🔬 技术原理 ★★★★★ 📚🔧&quot;">​</a></h2><h3 id="_4-1-功率路径" tabindex="-1">4.1 功率路径 <a class="header-anchor" href="#_4-1-功率路径" aria-label="Permalink to &quot;4.1 功率路径&quot;">​</a></h3><p>三相输入电压经过输入电感后，由有源开关和二极管网络控制每相电流流向上母线、下母线或中点。由于输出是分裂母线，控制器必须同时关注总母线电压：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vdc = Vdc_upper + Vdc_lower</span></span></code></pre></div><p>以及中点偏差：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vneutral_error = Vdc_upper - Vdc_lower</span></span></code></pre></div><h3 id="_4-2-控制结构" tabindex="-1">4.2 控制结构 <a class="header-anchor" href="#_4-2-控制结构" aria-label="Permalink to &quot;4.2 控制结构&quot;">​</a></h3><table tabindex="0"><thead><tr><th>环节</th><th>输入</th><th>输出</th><th>验收标准</th></tr></thead><tbody><tr><td>PLL/相位提取</td><td>三相电压</td><td>电网角度</td><td>相位误差有界</td></tr><tr><td>电压外环</td><td><code>Vdc_ref - Vdc</code></td><td>有功电流幅值</td><td>负载阶跃后无持续振荡</td></tr><tr><td>电流内环</td><td>三相电流参考/实测</td><td>调制量</td><td>输入电流正弦且与电压同相</td></tr><tr><td>中点平衡</td><td><code>Vdc_upper - Vdc_lower</code></td><td>冗余状态/零序调节</td><td>中点偏差不单调漂移</td></tr></tbody></table><h3 id="_4-3-外环带宽约束" tabindex="-1">4.3 外环带宽约束 <a class="header-anchor" href="#_4-3-外环带宽约束" aria-label="Permalink to &quot;4.3 外环带宽约束&quot;">​</a></h3><p>PFC 电压外环不能无限做快。外环太慢，负载阶跃时母线跌落明显；外环太快，可能把两倍工频功率脉动传递到输入电流参考，导致输入电流畸变。工程上需要在母线动态响应和输入电流质量之间折中。</p><h3 id="_4-4-中点平衡" tabindex="-1">4.4 中点平衡 <a class="header-anchor" href="#_4-4-中点平衡" aria-label="Permalink to &quot;4.4 中点平衡&quot;">​</a></h3><p>维也纳整流器也是三电平结构，上下电容电压平衡不是自然保证的。中点平衡策略通常通过冗余开关状态、零序注入或电流方向相关的调制修正实现。仿真中必须记录 <code>Vdc_upper</code> 和 <code>Vdc_lower</code>，只看总 <code>Vdc</code> 不足以判断系统正确。</p><hr><h2 id="_5-🔗-交叉视角-★★★★★-💡🔧" tabindex="-1">5. 🔗 交叉视角 ★★★★★ 💡🔧 <a class="header-anchor" href="#_5-🔗-交叉视角-★★★★★-💡🔧" aria-label="Permalink to &quot;5. 🔗 交叉视角 ★★★★★ 💡🔧&quot;">​</a></h2><h3 id="_5-1-与电机控制的连接" tabindex="-1">5.1 与电机控制的连接 <a class="header-anchor" href="#_5-1-与电机控制的连接" aria-label="Permalink to &quot;5.1 与电机控制的连接&quot;">​</a></h3><p>维也纳整流器的输出母线直接约束逆变器最大电压。对 lxfoc 来说，最关键的连接不是把 Vienna 控制并入 lxfoc，而是把实时 <code>vbus</code> 和母线质量传递给电机控制侧：</p><ul><li><code>vbus</code> 影响 <code>lxfoc_control_current</code> 的电压限幅。</li><li>母线跌落会触发弱磁、降额或保护。</li><li>母线纹波会调制 SVPWM 输出，需要在实测 trace 中记录。</li></ul><h3 id="_5-2-与弱磁控制的连接" tabindex="-1">5.2 与弱磁控制的连接 <a class="header-anchor" href="#_5-2-与弱磁控制的连接" aria-label="Permalink to &quot;5.2 与弱磁控制的连接&quot;">​</a></h3><p>弱磁边界取决于可用电压。当 Vienna 外环响应较慢或母线跌落较深时，FOC 可能提前进入弱磁或发生 <code>uq</code> 限幅。弱磁控制不能只按额定母线设计，必须使用实时 <code>vbus</code>。</p><h3 id="_5-3-与整机保护的连接" tabindex="-1">5.3 与整机保护的连接 <a class="header-anchor" href="#_5-3-与整机保护的连接" aria-label="Permalink to &quot;5.3 与整机保护的连接&quot;">​</a></h3><p>前端故障和后级故障会互相影响。输入缺相、PFC 限流、母线过压、母线欠压、逆变器过流都需要在统一故障流中记录，否则问题会被误判为“电机控制参数没调好”。</p><hr><h2 id="_6-🎯-工程案例-★★★★★-🔧🎯" tabindex="-1">6. 🎯 工程案例 ★★★★★ 🔧🎯 <a class="header-anchor" href="#_6-🎯-工程案例-★★★★★-🔧🎯" aria-label="Permalink to &quot;6. 🎯 工程案例 ★★★★★ 🔧🎯&quot;">​</a></h2><h3 id="案例-vienna-前端给伺服逆变器供电" tabindex="-1">案例：Vienna 前端给伺服逆变器供电 <a class="header-anchor" href="#案例-vienna-前端给伺服逆变器供电" aria-label="Permalink to &quot;案例：Vienna 前端给伺服逆变器供电&quot;">​</a></h3><p><strong>系统目标：</strong></p><ul><li>三相 AC 输入</li><li>Vienna PFC 输出 700 V 直流母线</li><li>后级逆变器驱动 PMSM</li><li>lxfoc 记录 <code>vbus_V</code>、dq 电压和故障标志</li></ul><p>推荐输出指标：</p><table tabindex="0"><thead><tr><th>指标</th><th style="text-align:right;">70% 阶段目标</th></tr></thead><tbody><tr><td>功率因数 PF</td><td style="text-align:right;">&gt; 0.98</td></tr><tr><td>输入电流 THD</td><td style="text-align:right;">&lt; 5% 或明确说明未达标原因</td></tr><tr><td>母线稳态误差</td><td style="text-align:right;">&lt; 2%</td></tr><tr><td>中点电压偏差</td><td style="text-align:right;">&lt; 5% Vdc</td></tr></tbody></table><p>必须保存输入电压、输入电流、母线电压、上下电容电压和调制量。</p><p><strong>联调步骤：</strong></p><ol><li>Vienna 空载建立母线，检查 <code>Vdc_upper</code> 和 <code>Vdc_lower</code>。</li><li>接假负载阶跃，验证输入电流 THD 和母线恢复时间。</li><li>接逆变器但不开电机，验证母线采样和保护阈值。</li><li>低功率运行 FOC，记录 <code>vbus_V</code> 与 <code>ud_V/uq_V</code>。</li><li>做加速阶跃，检查母线跌落是否导致电压限幅或弱磁动作。</li></ol><hr><h2 id="_7-📝-实践练习-★★★★★-🎯📝" tabindex="-1">7. 📝 实践练习 ★★★★★ 🎯📝 <a class="header-anchor" href="#_7-📝-实践练习-★★★★★-🎯📝" aria-label="Permalink to &quot;7. 📝 实践练习 ★★★★★ 🎯📝&quot;">​</a></h2><h3 id="练习-1-控制环识别" tabindex="-1">练习 1：控制环识别 <a class="header-anchor" href="#练习-1-控制环识别" aria-label="Permalink to &quot;练习 1：控制环识别&quot;">​</a></h3><p>Vienna PFC 中电压外环的输出通常是什么？</p><p><strong>参考答案：</strong></p><p>通常输出有功电流幅值或等效功率指令，再由电流内环生成三相输入电流参考。</p><h3 id="练习-2-母线记录" tabindex="-1">练习 2：母线记录 <a class="header-anchor" href="#练习-2-母线记录" aria-label="Permalink to &quot;练习 2：母线记录&quot;">​</a></h3><p>为什么实测只记录总 <code>Vdc</code> 不够，还要记录 <code>Vdc_upper</code> 和 <code>Vdc_lower</code>？</p><p><strong>参考答案：</strong></p><p>总 <code>Vdc</code> 可能正常，但上下电容已经不平衡。中点偏差会改变器件电压应力、调制裕量和后级逆变器参考点。</p><h3 id="练习-3-foc-影响" tabindex="-1">练习 3：FOC 影响 <a class="header-anchor" href="#练习-3-foc-影响" aria-label="Permalink to &quot;练习 3：FOC 影响&quot;">​</a></h3><p>Vienna 前端负载阶跃时母线短暂跌落，会怎样影响 FOC？</p><p><strong>参考答案：</strong></p><p>可用电压降低，<code>ud/uq</code> 更容易触发限幅，电流跟踪误差可能增大，高速时弱磁可能提前介入，严重时触发欠压保护。</p><h3 id="练习-4-外环带宽" tabindex="-1">练习 4：外环带宽 <a class="header-anchor" href="#练习-4-外环带宽" aria-label="Permalink to &quot;练习 4：外环带宽&quot;">​</a></h3><p>为什么 PFC 电压外环不能为了母线更稳而无限提高带宽？</p><p><strong>参考答案：</strong></p><p>外环过快可能把母线低频功率脉动传递到输入电流参考，导致输入电流畸变和功率因数下降。需要在母线动态和输入电流质量之间折中。</p><hr><h2 id="_8-📚-正确性证据" tabindex="-1">8. 📚 正确性证据 <a class="header-anchor" href="#_8-📚-正确性证据" aria-label="Permalink to &quot;8. 📚 正确性证据&quot;">​</a></h2><p>主要对标：</p><ul><li>Mohan, <em>Power Electronics</em>.</li><li>Erickson and Maksimovic, <em>Fundamentals of Power Electronics</em>.</li><li>TI/Infineon Vienna rectifier reference design notes.</li></ul><p>本模块的 proof 文件位于 <code>_proofs/power-path/PP-10-Vienna-Rectifier.module-proof.yaml</code>。</p>',77))])}const P=r(l,[["render",c]]);export{E as __pageData,P as default};
